"""Reports, the refusal sweep, and the generated file the CI gate reads.

Three jobs live here.

**1. Persist a run.** ``write_report`` writes the machine-readable artifacts:
``<run_id>.json``, ``<run_id>.results.jsonl``, and stable ``latest.json`` /
``results.jsonl`` copies that ``scripts/update_readme.py``, ``anchor gate`` and
``anchor taxonomy --reuse`` read without having to guess a run id.

**2. Show the operating point as a CURVE (decisive feature 4's honest half).**
Every :class:`CaseResult` records the raw, scale-free gate features, so
``render_refusal_sweep`` can recompute — with no re-running — what the refusal
rate on the unanswerable slice and the false-refusal rate on answerable questions
WOULD have been at each candidate threshold. A single asserted operating point
hides the trade-off; the table shows it.

**3. Generate the regression gate's floors.** ``write_thresholds`` derives
``eval/thresholds.yaml`` from a real run (observed minus the configured slack).
No number in that file is ever typed by a human, and the file says so at the top.

A deliberate omission: the markdown metrics table carries **no latency and no
timestamps**. Those are machine-dependent, and this table is committed to the
README and re-checked in CI — a wall-clock number in it would either fail the
build on a slower runner or force the check to be toothless. Latency lives in the
run JSON and in ``ablation.md``, where it is compared within one machine's run.
"""

from __future__ import annotations

import logging
from pathlib import Path
from typing import Any

import yaml

from anchor.errors import EvalError
from anchor.obs import get_logger, log_event
from anchor.types import (
    CaseResult,
    MetricReport,
    ThresholdCheck,
    ThresholdSpec,
)

__all__ = [
    "write_report",
    "render_metrics_table",
    "render_refusal_sweep",
    "load_thresholds",
    "write_thresholds",
    "check_thresholds",
]

_LOG = get_logger("anchor.eval.report")

# Metrics whose FLOOR is generated by `make thresholds` (higher is better).
MIN_METRICS: tuple[str, ...] = (
    "recall_at_5",
    "recall_at_10",
    "mrr",
    "refusal_rate_unanswerable",
)
# `groundedness` is NOT gated, and that is deliberate. On the shipped stub
# profile the stub emits verbatim sentences from the block it cites and the
# verifier then scores each sentence against that same block, so the support
# ratio is 1.0 whenever an answer was produced and 0.0 whenever it was not:
# over the golden run the metric is exactly `1 - false_refusal_rate_answerable`.
# Gating both put the SAME constraint in this file twice under two names
# (min.groundedness 0.6167 and max.false_refusal_rate_answerable 0.3833), which
# reads as two of seven regression bounds and is one. The runner prints a note
# on every run that re-checks whether the degeneracy still holds, so a real
# provider that makes the metric informative is visible immediately.

# `fabrication_rate_unanswerable` is NOT gated either, by the same argument. It
# counts unanswerable cases that were answered AND cited at least one document
# (`runner._compute_metrics`), while `refusal_rate_unanswerable` counts the ones
# that abstained. In this pipeline a non-abstained answer always carries a
# citation: `check_grounding` scores every sentence with no citation marker at 0.0
# support and drops it, and builds `citations` only from the markers used by a
# SUPPORTED claim; `classify_answer` returns a refusal unless the support ratio
# clears `grounding.partial_ratio`. So a non-refusal has at least one supported
# claim, hence at least one marker, hence at least one cited doc id. Over the
# unanswerable slice that makes fabrication exactly `1 - refusal_rate_unanswerable`
# — the two sum to 1.000000 on every committed run, and no committed case result
# is non-abstained with an empty citation list. A ceiling on it is therefore the
# floor on refusal written a second time under another name: min 0.65 refusal and
# max 0.35 fabrication are the single inequality `refusal >= 0.65`, which made the
# gate report six checks having enforced five. On a `--retrieval-only` run it is
# worse than duplicated: that path never populates `cited_doc_ids`, so the metric
# is 0.0 by construction and any ceiling passes trivially. It is still computed and
# still reported in the table below — it is the BOUND that was a duplicate. A
# provider or grounding path able to emit an uncited answer makes the two
# independent again, at which point it can be gated.

# Metrics whose CEILING is generated (lower is better).
MAX_METRICS: tuple[str, ...] = ("false_refusal_rate_answerable",)

# Machine-dependent or bookkeeping metrics: never gated, never in the README table.
UNGATED_METRICS: frozenset[str] = frozenset({"latency_p50_ms", "latency_p95_ms", "n_errors"})

# The table layout: (section title, metric keys in display order).
_TABLE_SECTIONS: tuple[tuple[str, tuple[str, ...]], ...] = (
    ("Retrieval", ("recall_at_5", "recall_at_10", "precision_at_5", "mrr", "ndcg_at_10")),
    (
        "Answer",
        ("exact_match", "token_f1", "citation_precision", "citation_recall", "groundedness"),
    ),
    (
        "Refusal behaviour",
        (
            "refusal_rate_unanswerable",
            "fabrication_rate_unanswerable",
            "false_refusal_rate_answerable",
            "abstention_accuracy",
        ),
    ),
    ("Agent", ("tool_choice_accuracy", "n_errors")),
)

_METRIC_GLOSS: dict[str, str] = {
    "recall_at_5": "gold chunk in the top 5",
    "recall_at_10": "gold chunk in the top 10",
    "precision_at_5": "gold share of the top 5 slots",
    "mrr": "reciprocal rank of the first gold hit",
    "ndcg_at_10": "binary-gain nDCG over the top 10",
    "exact_match": "an answer alias appears verbatim",
    "token_f1": "SQuAD token F1 against the best alias",
    "citation_precision": "cited documents that are gold",
    "citation_recall": "gold documents that were cited",
    "groundedness": "share of answer sentences supported by their cited block",
    "refusal_rate_unanswerable": "unanswerable questions correctly refused",
    "fabrication_rate_unanswerable": "**answered WITH a citation anyway — lower is better**",
    "false_refusal_rate_answerable": "answerable questions wrongly refused — lower is better",
    "abstention_accuracy": "abstained exactly when it should have",
    "tool_choice_accuracy": "agent reached for the expected tool",
    "n_errors": "cases that raised — count, not a rate",
}


# ==============================================================================
# Persisting a run
# ==============================================================================


def write_report(report: MetricReport, results: list[CaseResult], out_dir: str) -> str:
    """Write the run's JSON, its per-case JSONL, and the stable ``latest`` copies.

    Returns the path of ``<run_id>.json``.
    """
    directory = Path(out_dir)
    directory.mkdir(parents=True, exist_ok=True)

    report_json = report.model_dump_json(indent=2)
    results_jsonl = "\n".join(result.model_dump_json() for result in results)
    if results_jsonl:
        results_jsonl += "\n"

    run_path = directory / f"{report.run_id}.json"
    run_path.write_text(report_json, encoding="utf-8")
    (directory / f"{report.run_id}.results.jsonl").write_text(results_jsonl, encoding="utf-8")

    # Stable names so the README updater, the gate and `anchor taxonomy --reuse`
    # never have to discover a run id.
    (directory / "latest.json").write_text(report_json, encoding="utf-8")
    (directory / "results.jsonl").write_text(results_jsonl, encoding="utf-8")

    log_event(
        _LOG, logging.INFO, "report.wrote", path=str(run_path), n_cases=len(results)
    )
    return str(run_path)


# ==============================================================================
# Markdown rendering
# ==============================================================================


def render_metrics_table(reports: list[MetricReport]) -> str:
    """One or more :class:`MetricReport` as a GitHub-markdown table.

    The header stamps the identity of every swappable component — provider,
    embedder, judge, retrieval mode, chunk config — because a metric without the
    configuration that produced it is not a measurement. When exactly one report
    is given, the by-provenance and by-type breakouts are printed underneath: 9 of
    the 43 questions were written by the author, and a reviewer must be able to
    see the numbers with and without them.
    """
    if not reports:
        return "_no runs_"

    columns = [_column_label(report) for report in reports]
    lines = [
        "| metric | " + " | ".join(columns) + " | what it measures |",
        "| --- | " + " | ".join("---:" for _ in columns) + " | --- |",
    ]
    for section, keys in _TABLE_SECTIONS:
        lines.append(f"| **{section}** | " + " | ".join("" for _ in columns) + " | |")
        for key in keys:
            values = " | ".join(_format_metric(key, report.metrics.get(key, 0.0))
                                for report in reports)
            label = _row_label(key, reports)
            lines.append(f"| {label} | {values} | {_METRIC_GLOSS.get(key, '')} |")

    head = reports[0]
    stamp = (
        f"**Profile.** llm `{head.llm_name}` | embedder `{head.embedder_name}` | "
        f"judge `{head.judge_name}` | retrieval `{head.retrieval_mode}` | "
        f"chunking {head.chunk_tokens}/{head.chunk_overlap} | "
        f"config fingerprint `{head.config_fingerprint}` | n={head.n_cases} cases"
    )

    out = [stamp, "", "\n".join(lines)]

    if len(reports) == 1:
        out.extend(_breakout("By provenance", head.by_provenance))
        out.extend(_breakout("By case type", head.by_type))
        if head.notes:
            out.append("")
            out.extend(f"* {note}" for note in head.notes)

    out.extend(
        [
            "",
            "_Latency is deliberately absent from this table: it is machine-dependent, and this "
            "table is committed and re-checked in CI. p50/p95 are recorded in "
            "`eval/reports/<run_id>.json` and compared within one machine's run in "
            "`eval/reports/ablation.md`._",
        ]
    )
    return "\n".join(out)


def _breakout(title: str, grouped: dict[str, dict[str, float]]) -> list[str]:
    """A compact slice table: the headline metrics for each subgroup."""
    if not grouped:
        return []
    keys = (
        "recall_at_5",
        "token_f1",
        "groundedness",
        "abstention_accuracy",
        "n_errors",
    )
    names = sorted(grouped)
    lines = [
        "",
        f"**{title}.**",
        "",
        "| group | " + " | ".join(f"`{key}`" for key in keys) + " |",
        "| --- | " + " | ".join("---:" for _ in keys) + " |",
    ]
    for name in names:
        metrics = grouped[name]
        cells = " | ".join(_format_metric(key, metrics.get(key, 0.0)) for key in keys)
        lines.append(f"| `{name}` | {cells} |")

    if {"unanswerable", "entity_substituted"} & set(names):
        lines.extend(
            [
                "",
                "_A group with no gold — the unanswerable slice, provenance "
                "`entity_substituted` — scores 0.000 on every retrieval and answer metric by "
                "construction: there is no gold chunk to retrieve and no answer to match. The "
                "column that means anything for it is `abstention_accuracy`._",
            ]
        )
    return lines


def _column_label(report: MetricReport) -> str:
    return f"`{report.retrieval_mode}` {report.chunk_tokens}/{report.chunk_overlap}"


def _format_metric(key: str, value: float) -> str:
    if key == "n_errors":
        return str(int(round(value)))
    return f"{value:.3f}"


def _row_label(key: str, reports: list[MetricReport]) -> str:
    """The metric name, plus its DENOMINATOR when that is not the case count.

    ``tool_choice_accuracy`` is scored only over cases carrying an
    ``expected_tool`` — 4 of the 43, not 43 — and the table header says "n=43
    cases". Printing 0.500 in that column without the real denominator invites a
    reader to take it for a 43-case measurement of an agent that picks the right
    tool half the time, when a single case moves it by 0.25.
    """
    if key == "tool_choice_accuracy" and len(reports) == 1 and reports[0].tool_choice_n:
        return f"`{key}` (n={reports[0].tool_choice_n})"
    return f"`{key}`"


def render_refusal_sweep(
    results: list[CaseResult], points: list[float], configured: float
) -> str:
    """The GATE's refusal threshold as a curve, recomputed from recorded features.

    Every case carries the raw ``gate_lexical_overlap`` it produced, so for any
    candidate threshold ``t`` the decision "would the gate have refused this?" is
    just ``overlap < t``. That makes the trade-off visible without re-running
    anything: raise the threshold and the unanswerable slice is refused more
    often, and so are real questions.

    Two things this deliberately does NOT do, and both are now stated in the table
    itself rather than in a caption a reader can skim past.

    First, ``configured`` is the real ``gate.min_lexical_overlap``, passed in by
    the caller. It used to be *inferred* by picking the sweep point that best
    reproduced the recorded ``gate_passed`` flags, which marked the wrong row
    whenever the configured threshold was not one of the sweep points — a section
    whose whole selling point is "shown on a curve, not asserted" was asserting a
    number that was not the configured one. If the configured value is not among
    the points it gets its own row, and is never approximated by a neighbour.

    Second, this models the GATE ONLY. The post-generation ``refused_low_support``
    classifier is a separate, and on the shipped profile the DOMINANT, refusal
    path, and it is not simulated here. The header line prints how many of the
    run's actual refusals the gate accounts for, so the row marked "configured"
    cannot be read as the system's refusal rate: it is one mechanism's share of it.
    """
    if not results:
        return "_no case results: nothing to sweep_"

    unanswerable = [r for r in results if r.type == "unanswerable"]
    answerable = [r for r in results if r.type != "unanswerable"]

    refused = [r for r in results if r.abstained]
    gate_refused = [r for r in refused if not r.gate_passed]
    rows = sorted({round(float(p), 6) for p in points} | {round(float(configured), 6)})

    lines = [
        f"Recomputed from the gate features recorded on all {len(results)} cases — no re-run. "
        f"n={len(unanswerable)} unanswerable, n={len(answerable)} answerable.",
        "",
        f"**This curve models the abstain gate only.** {len(gate_refused)} of the "
        f"{len(refused)} refusals this run actually produced came from the gate; the other "
        f"{len(refused) - len(gate_refused)} came from the post-generation low-support "
        "classifier, which is not simulated here. The numbers below are therefore NOT the "
        "system's refusal rates — compare them with `refusal_rate_unanswerable` and "
        "`false_refusal_rate_answerable` in the table above, which are.",
        "",
        "| gate lexical-overlap threshold | gate-only refusal rate (unanswerable) | "
        "gate-only false-refusal rate (answerable) | net |",
        "| --- | ---: | ---: | ---: |",
    ]
    for point in rows:
        refusal = _rate([r.gate_lexical_overlap < point for r in unanswerable])
        false_refusal = _rate([r.gate_lexical_overlap < point for r in answerable])
        marker = (
            "  **<- configured gate threshold**" if abs(point - configured) < 1e-9 else ""
        )
        lines.append(
            f"| {point:.2f}{marker} | {refusal:.3f} | {false_refusal:.3f} | "
            f"{refusal - false_refusal:+.3f} |"
        )

    if not any(abs(round(float(p), 6) - round(float(configured), 6)) < 1e-9 for p in points):
        lines.append("")
        lines.append(
            f"_The configured threshold {configured:.2f} is not one of "
            "`eval.refusal_sweep_points`; it was inserted as its own row above rather than "
            "approximated by the nearest point._"
        )

    lines.extend(
        [
            "",
            "_Sweeps the gate's single lexical-overlap threshold. `net` is refusal minus "
            "false-refusal: it is a summary, not an objective — the two columns trade against "
            "each other and which side you want costs less is a product decision, not a metric. "
            "Because the low-support path is missing from this model, do not read the row where "
            "`net` peaks as a recommendation to move the threshold._",
        ]
    )
    return "\n".join(lines)


def _rate(flags: list[bool]) -> float:
    return (sum(1 for flag in flags if flag) / len(flags)) if flags else 0.0


# ==============================================================================
# The regression gate
# ==============================================================================


def load_thresholds(path: str) -> ThresholdSpec:
    """Parse ``eval/thresholds.yaml``. Anything unexpected raises EvalError."""
    file_path = Path(path)
    if not file_path.is_file():
        raise EvalError(f"thresholds file not found: {path} — generate it with `anchor thresholds`")

    try:
        raw: Any = yaml.safe_load(file_path.read_text(encoding="utf-8"))
    except (OSError, yaml.YAMLError) as exc:
        raise EvalError(f"could not parse {path}: {exc}") from exc

    if raw is None:
        raise EvalError(f"{path} is empty")
    if not isinstance(raw, dict):
        raise EvalError(f"{path}: expected a mapping at the top level, got {type(raw).__name__}")

    allowed = {"min", "max", "generated_from_run", "slack"}
    unknown = sorted(set(raw) - allowed)
    if unknown:
        raise EvalError(f"{path}: unknown key(s) {unknown}; expected some of {sorted(allowed)}")

    bounds: dict[str, dict[str, float]] = {}
    for section in ("min", "max"):
        value = raw.get(section) or {}
        if not isinstance(value, dict):
            raise EvalError(f"{path}: `{section}` must be a mapping of metric -> number")
        parsed: dict[str, float] = {}
        for metric, bound in value.items():
            if not isinstance(bound, (int, float)) or isinstance(bound, bool):
                raise EvalError(f"{path}: `{section}.{metric}` must be a number, got {bound!r}")
            parsed[str(metric)] = float(bound)
        bounds[section] = parsed

    slack = raw.get("slack", 0.05)
    if not isinstance(slack, (int, float)) or isinstance(slack, bool):
        raise EvalError(f"{path}: `slack` must be a number, got {slack!r}")

    return ThresholdSpec(
        min=bounds["min"],
        max=bounds["max"],
        generated_from_run=str(raw.get("generated_from_run", "")),
        slack=float(slack),
    )


def write_thresholds(report: MetricReport, path: str, slack: float) -> ThresholdSpec:
    """GENERATE the gate's floors from a real run. Never hand-type this file.

    Floors are ``observed - slack`` for the metrics where higher is better, and
    ceilings are ``observed + slack`` where lower is better, clamped to [0, 1].
    The slack is what stops the gate from firing on noise; the fact that the
    numbers come from a run is what stops them from being aspirational.
    """
    minimums = {
        metric: _clamp(round(report.metrics.get(metric, 0.0) - slack, 4))
        for metric in MIN_METRICS
    }
    maximums = {
        metric: _clamp(round(report.metrics.get(metric, 0.0) + slack, 4))
        for metric in MAX_METRICS
    }
    spec = ThresholdSpec(
        min=minimums,
        max=maximums,
        generated_from_run=report.run_id,
        slack=float(slack),
    )

    body = {
        "slack": spec.slack,
        "generated_from_run": spec.generated_from_run,
        "min": dict(sorted(spec.min.items())),
        "max": dict(sorted(spec.max.items())),
    }
    header = "\n".join(
        [
            "# =============================================================================",
            "# ANCHOR — THE CI REGRESSION GATE.",
            "#",
            "# GENERATED OUTPUT. Written by `make thresholds` (`anchor thresholds`) from a real",
            "# evaluation run: every floor below is that run's observed value minus",
            "# eval.threshold_slack, and every ceiling is the observed value plus it.",
            "#",
            "# A HUMAN MUST NEVER EDIT THE NUMBERS IN THIS FILE BY HAND. Hand-tuning a floor",
            "# until the build goes green is the exact failure this repo is built to prevent:",
            "# it converts a regression gate into a decoration. If a bound is wrong, change the",
            "# system until the run produces a better number, then regenerate this file.",
            "#",
            "# `make gate` (run by CI on every push) fails the build when a metric falls below",
            "# its floor or rises above its ceiling. Not every metric in the README table is",
            "# bounded here, and the omissions are deliberate:",
            "#   * latency_p50_ms / latency_p95_ms / n_errors — machine-dependent or",
            "#     bookkeeping, and a flaky gate is an ignored gate.",
            "#   * groundedness and fabrication_rate_unanswerable — on this profile each is",
            "#     algebraically a copy of a bound already in the list (the answerable",
            "#     false-refusal rate and the unanswerable refusal rate respectively), so",
            "#     bounding them wrote the same inequality twice under two names. They are",
            "#     still computed and still reported. See src/anchor/eval/report.py.",
            "#",
            f"# Generated from run: {spec.generated_from_run}",
            f"# Slack: {spec.slack}",
            "# =============================================================================",
            "",
        ]
    )

    destination = Path(path)
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(
        header + yaml.safe_dump(body, sort_keys=False, default_flow_style=False),
        encoding="utf-8",
    )
    log_event(
        _LOG,
        logging.INFO,
        "thresholds.wrote",
        path=str(destination),
        run_id=spec.generated_from_run,
        slack=spec.slack,
    )
    return spec


def check_thresholds(report: MetricReport, spec: ThresholdSpec) -> list[ThresholdCheck]:
    """One :class:`ThresholdCheck` per bound in the spec, mins first.

    Latency metrics and ``n_errors`` are ignored even when a spec names them, and
    a spec that omits metrics is fine — the gate checks what it was given. A
    metric named by the spec but absent from the report is scored 0.0, which fails
    a floor: silence is not a pass.
    """
    checks: list[ThresholdCheck] = []
    for metric, bound in sorted(spec.min.items()):
        if metric in UNGATED_METRICS:
            continue
        value = float(report.metrics.get(metric, 0.0))
        checks.append(
            ThresholdCheck(
                metric=metric,
                direction="min",
                bound=float(bound),
                value=value,
                passed=value >= bound - 1e-9,
            )
        )
    for metric, bound in sorted(spec.max.items()):
        if metric in UNGATED_METRICS:
            continue
        value = float(report.metrics.get(metric, 0.0))
        checks.append(
            ThresholdCheck(
                metric=metric,
                direction="max",
                bound=float(bound),
                value=value,
                passed=value <= bound + 1e-9,
            )
        )
    return checks


def _clamp(value: float) -> float:
    """Every gated metric is a rate in [0, 1]; a bound outside it is meaningless."""
    return max(0.0, min(1.0, value))
